#!/usr/bin/env python3
"""
JNTUACEA Attendance - web app (Vercel serverless)
=================================================
  /            -> landing page (Download App) + SEO
  /app         -> in-browser attendance checker (Auto Sync + Quick Entry)
  /app/sync    -> POST: server-side portal sync (JSON)
  /manifest.json, /sw.js, /static/icons -> PWA (add to home screen)
  /robots.txt, /sitemap.xml -> Google indexing
  /downloads/app.apk -> the Android APK (embedded, rewrite-proof)
"""

