@app.route('/manifest.json')
def manifest():
    return Response(MANIFEST_JSON, mimetype='application/manifest+json')


@app.route('/sw.js')
def sw():
    return Response(SW_JS, mimetype='application/javascript')


@app.route('/app/status')
def app_status():
    o, c = _portal_status()
    return Response(_json.dumps({'open': o, 'captcha': c}), mimetype='application/json')


@app.route('/app/sync', methods=['POST'])
def app_sync():
    u = (request.form.get('username') or '').strip().upper()
    pw = (request.form.get('password') or '').strip()
    return Response(_json.dumps(app_page.app_sync_json(u, pw)),
                    mimetype='application/json')


def _icon(name):
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'static', name)
    with open(p, 'rb') as f:
        return f.read()


@app.route('/', defaults={'path': ''}, methods=['GET', 'POST'])
@app.route('/api/index', defaults={'path': ''}, methods=['GET', 'POST'])
@app.route('/<path:path>', methods=['GET', 'POST'])
def index(path):
    p = (path or '').lower()
    # rewrite-proof handling (Vercel sends /api/index/<path>)
    if 'robots' in p:
        return Response('User-agent: *\nAllow: /\n\n'
                        'Sitemap: https://attendance-portal-uk21.vercel.app/sitemap.xml\n',
                        mimetype='text/plain')
    if 'sitemap' in p:
        xml = ('<?xml version="1.0" encoding="UTF-8"?>\n'
               '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
               '  <url><loc>https://attendance-portal-uk21.vercel.app/</loc><priority>1.0</priority></url>\n'
               '  <url><loc>https://attendance-portal-uk21.vercel.app/app</loc><priority>0.9</priority></url>\n'
               '</urlset>\n')
        return Response(xml, mimetype='application/xml')
    if 'manifest' in p:
        return Response(MANIFEST_JSON, mimetype='application/manifest+json')
    if 'sw.js' in p:
        return Response(SW_JS, mimetype='application/javascript')
    if 'icon-192' in p:
        return Response(_icon('icon-192.png'), mimetype='image/png')
    if 'icon-512' in p:
        return Response(_icon('icon-512.png'), mimetype='image/png')
    if 'bm.js' in p:
        pj = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'bm.js')
        with open(pj, 'r', encoding='utf-8') as f:
            return Response(f.read(), mimetype='application/javascript')
    if 'apk' in p:
        return Response(_b64.b64decode(APK_B64),
                        mimetype='application/vnd.android.package-archive',
                        headers={'Content-Disposition':
                                 'attachment; filename="JNTUACEA-Attendance.apk"'})
    if 'status' in p:
        o, c = _portal_status()
        return Response(_json.dumps({'open': o, 'captcha': c}), mimetype='application/json')
    if request.method == 'POST' and 'sync' in p:
        u = (request.form.get('username') or '').strip().upper()
        pw = (request.form.get('password') or '').strip()
        return Response(_json.dumps(app_page.app_sync_json(u, pw)),
                        mimetype='application/json')
    if p == 'app' or p.endswith('/app'):
        return Response(app_page.app_page_html(), mimetype='text/html')
    return Response(render_template_string(LANDING), mimetype='text/html')


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '8020')), debug=False)
